"""Standalone, offline evidence research report; no execution controls."""
import base64
from datetime import datetime, timezone
import html
import json
from pathlib import Path
from .defi_daily import atomic_text
from .evidence_policy import CAPS


def render_report(snapshot,evaluation=None):
    evaluation=evaluation or {}
    stamp=datetime.fromtimestamp(snapshot.get('generated_at',0),timezone.utc).strftime('%d %b %Y · %H:%M UTC')
    font_path=Path(__file__).parent/'static'/'fonts'/'Vazirmatn-Regular.woff2'
    font=base64.b64encode(font_path.read_bytes()).decode('ascii') if font_path.is_file() else ''
    names={'technical':'Price & trend','flow':'Daily buying pressure','macro':'DeFi conditions','whale':'Wallet observations','news':'News context'}
    cards=[]
    for group,cap in CAPS.items():
        coverage=[p.get('coverage',{}).get(group,'not_available_as_of') for p in snapshot.get('packets',{}).values()]
        count=coverage.count('eligible')
        cards.append('<article class="signal"><div class="eyebrow">%s</div><h3>%s</h3><div class="weight">0%% <small>active influence</small></div><div class="track"><i style="width:%s%%"></i></div><p>Experimental ceiling <b>%s%%</b><br>%s of 3 asset packets have eligible observations</p><span class="chip">Awaiting prospective calibration</span></article>' % (html.escape(group),names[group],cap*100,int(cap*100),count))
    sources=[]
    for source,row in sorted(snapshot.get('sources',{}).items()):
        sources.append('<div class="source"><span class="dot %s"></span><div><b>%s</b><small>%s</small></div></div>' % ('green' if row.get('status')=='ok' else '',html.escape(source.replace('_',' ').title()),html.escape(str(row.get('status','unknown')))))
    data=json.dumps(evaluation,allow_nan=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    page=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Evidence strategy · Bitpin research</title><style>
@font-face{font-family:Vazirmatn;src:url(data:font/woff2;base64,__FONT__);font-display:swap}
*{box-sizing:border-box}body{margin:0;background:#08111f;color:#eaf0f8;font:14px/1.7 Vazirmatn,system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:48px 28px}a{color:#b8afff}button,select{font:inherit}button:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid #cebcff;outline-offset:4px}header{display:flex;justify-content:space-between;gap:24px;align-items:flex-start}.eyebrow{color:#b5a7ee;letter-spacing:.14em;text-transform:uppercase;font-size:11px;font-weight:700}h1{font-size:clamp(34px,5vw,48px);line-height:1.2;letter-spacing:-.04em;margin:12px 0}h2{font-size:23px;letter-spacing:-.02em;margin:8px 0}h3{font-size:17px;margin:8px 0}p{color:#a9b9cf;margin:10px 0}.intro{max-width:810px;font-size:15px}.badge,.chip{display:inline-block;border-radius:999px;padding:6px 12px;border:1px solid #4b4165;background:#24203b;color:#d3c3fa;font-size:12px}.badge{white-space:nowrap;margin-top:8px}.notice{background:linear-gradient(110deg,#242030,#182638);border:1px solid #4b425b;border-radius:20px;padding:22px 25px;margin:26px 0}.notice h2{font-size:19px}.notice p{margin-bottom:0}.section{margin-top:34px}.heading{display:flex;gap:20px;justify-content:space-between;align-items:center}.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap}label{font-size:12px;color:#b3c0d4}select{color:#e7edf9;background:#122034;border:1px solid #3a4a62;padding:10px 13px;border-radius:11px;min-height:44px}.signals{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;margin-top:20px}.signal,.card{border:1px solid #26384d;background:linear-gradient(145deg,#142239,#0f1a2c);border-radius:20px;padding:23px;min-width:0}.signal h3{font-size:15px;min-height:50px}.signal p{font-size:12px}.signal .chip{font-size:10px;padding:5px 8px;white-space:normal}.weight{font-size:29px;font-weight:700;font-variant-numeric:tabular-nums}.weight small{font-size:11px;font-weight:400;color:#9eb0c8;display:block}.track{height:5px;background:#091323;border-radius:6px;overflow:hidden;margin:15px 0}.track i{display:block;height:100%;background:#7565b6;opacity:.65}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:20px}.big{font-size:34px;font-weight:700;letter-spacing:-.03em;font-variant-numeric:tabular-nums}.sub{color:#9badc4;font-size:12px}.loss{color:#f6aba3}.positive{color:#94deba}.grid2{display:grid;grid-template-columns:1.4fr 1fr;gap:18px;margin-top:18px}.chart{height:auto;width:100%;display:block;margin-top:10px}.chart text{fill:#a9b9cf;font:12px Vazirmatn,system-ui}.table-wrap{overflow-x:auto;margin-top:16px}table{width:100%;border-collapse:collapse;font-size:12px;white-space:nowrap}th{text-align:left;color:#a7b8d0;font-weight:400}td,th{padding:13px 10px;border-bottom:1px solid #29384e}td{font-variant-numeric:tabular-nums}tr.chosen{background:#211f39}tr.chosen td:first-child{color:#cdbbff}.source{display:flex;gap:11px;align-items:center;padding:10px 0}.source b{font-size:12px}.source small{display:block;font-size:11px;color:#98acc7}.dot{height:8px;width:8px;background:#e5bd79;border-radius:50%;flex-shrink:0}.green{background:#73cfa6}.details{color:#a4b7ce;font-size:12px}ul{padding-left:21px}li{margin:8px 0}footer{font-size:11px;color:#8095b1;margin-top:28px;overflow-wrap:anywhere}.empty{padding:35px 0;color:#b5c3d6}svg{overflow:visible}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:1150px){.signals{grid-template-columns:repeat(3,minmax(0,1fr))}.grid2{grid-template-columns:1fr}.signal h3{min-height:0}}@media(max-width:720px){main{padding:28px 18px}header,.heading{display:block}.heading .controls{margin-top:15px}.signals{grid-template-columns:repeat(2,minmax(0,1fr))}.cards{grid-template-columns:1fr}.card,.signal{padding:20px}.notice{padding:20px}.big{font-size:32px}.signal:last-child{grid-column:1/-1}h1{font-size:36px}.intro{font-size:14px}}@media(prefers-reduced-motion:no-preference){.card,.signal{transition:border-color .15s ease}.card:hover,.signal:hover{border-color:#4d4774}}
</style></head><body><main><header><div><div class="eyebrow">Bitpin · Evidence research</div><h1>Measure before influence</h1></div><span class="badge">Research only · Live influence off</span></header><p class="intro">One auditable view of source quality, controlled influence and forecasts tested against later outcomes. Kimi remains the live allocator; this archive collects public evidence for prospective validation.</p>
<section class="notice"><div class="eyebrow">Current decision</div><h2>Keep the new strategy in shadow mode</h2><p>Small probability-score improvements do not establish profitable trades. The daily roundtrip comparator fails after declared costs. Newly collected flow, DeFi and wallet data do not have historical receipt coverage for this backtest.</p></section>
<section class="section"><div class="heading"><div><div class="eyebrow">Governance limits</div><h2>Evidence influence</h2></div><span class="chip">Untrained sources return weight to baseline</span></div><div class="signals">__SIGNALS__</div><p class="details">The bars show permitted ceilings. Every prospective predictive weight is currently zero. Source reliability, forecast skill and portfolio risk are assessed separately. Visible order depth helps assess execution, and does not cast an extra directional vote.</p></section>
<section class="section"><div class="heading"><div><div class="eyebrow">Frozen retrospective experiment</div><h2>What the free test found</h2></div><div class="controls"><label for="currency">Return currency</label><select id="currency"><option value="USDT">USDT relative</option><option value="IRT">IRT</option></select><label for="period">Period</label><select id="period"><option value="holdout">Final 180-day holdout</option><option value="development">Development folds</option></select></div></div><div id="results" aria-live="polite"></div></section>
<section class="section"><div class="grid2"><div class="card"><div class="eyebrow">Availability & provenance</div><h2>Prospective receipts</h2><p><b>__RECEIPTS__</b> unique snapshots archived. First archive observation is recorded independently of source event time and original collector receipt. Older copied data cannot be backdated.</p><div>__SOURCES__</div><p class="details">Published series can be revised. Wallet labels do not prove current ownership. TVL changes include price effects; DEX volume is activity rather than buying direction.</p></div><div class="card"><div class="eyebrow">Model experiment</div><h2>Fresh Kimi: not run</h2><p>No paid calls have been made for this research. The owner-run harness compares blinded raw histories with compact typed packets on the same fixed cases.</p><ul class="details"><li>Budget ceiling: $10, including reserved unknown failures.</li><li>Input-bound cache, strict JSON replies, no automatic retries.</li><li>Date blinding cannot remove all training-data contamination.</li><li>Prospective shadow forecasts provide the stronger test.</li></ul></div></div></section>
<section class="card section"><div class="eyebrow">Recorded forecasts</div><h2>Existing Kimi outcomes</h2><p id="recorded">No historical result loaded.</p><p class="details">Candidate p means target before hourly-close invalidation within its original plan horizon. It is distinct from three-class next-day direction and allocation confidence. Missing plans, unfinished outcomes and ambiguous paths remain censored.</p></section>
<footer>Snapshot: __STAMP__ · Orders: 0 · Model calls: 0 · No changes to live allocation. <a href="https://sites.stat.washington.edu/people/raftery/Research/PDF/Gneiting2007jasa.pdf">Proper scoring</a> · <a href="https://arxiv.org/abs/2309.17322">LLM lookahead research</a> · <a href="https://defillama.com/data-definitions">DefiLlama definitions</a></footer>
</main><script type="application/json" id="evaluation">__DATA__</script><script>
const E=JSON.parse(document.getElementById('evaluation').textContent); const $=id=>document.getElementById(id);
const pct=v=>v==null?'Unknown':(v*100).toFixed(2)+'%'; const num=v=>v==null?'Unknown':v.toFixed(4);
function update(){const currency=$('currency').value, period=$('period').value, q=(E.quantitative||{})[currency]; if(!q){$('results').innerHTML='<div class="empty">No historical result loaded</div>';return;}const h=q[period], chosen=(q.holdout||{}).selected_variant||'baseline', m=h.metrics||{}, pick=m[chosen]||m.baseline||{}, cmp=(h.comparators||{})[chosen]||{}, ci=(((h.paired_brier_improvement||{})[chosen]||{})['7']||{}); const variants=q.variants||[];
let rows=variants.map(v=>'<tr class="'+(v===chosen?'chosen':'')+'"><td>'+v+'</td><td>'+pct((m[v]||{}).accuracy)+'</td><td>'+num((m[v]||{}).brier)+'</td><td>'+num((m[v]||{}).logloss)+'</td><td>'+pct(((h.comparators||{})[v]||{}).return)+'</td></tr>').join('');
let points=(q.folds||[]).map((f,i)=>{const fm=f.metrics||{}; const improvement=((fm.baseline||{}).brier||0)-((fm[chosen]||{}).brier||0);return {i,improvement};});let scale=Math.max(.004,...points.map(p=>Math.abs(p.improvement)));let bars=points.map(p=>{const height=Math.abs(p.improvement)/scale*70, x=42+p.i*39, y=p.improvement>=0?90-height:90;return '<rect x="'+x+'" y="'+y+'" width="24" height="'+Math.max(1,height)+'" rx="3" fill="'+(p.improvement>=0?'#98cfbb':'#d89291')+'"/><text x="'+(x+8)+'" y="183">'+(p.i+1)+'</text>';}).join('');
$('results').innerHTML='<div class="cards"><article class="card"><div class="eyebrow">Frozen selection · '+chosen+'</div><div class="big">'+pct(pick.accuracy)+'</div><div class="sub">Directional accuracy · baseline '+pct((m.baseline||{}).accuracy)+'</div><p class="details">'+h.episode_count+' asset episodes across '+h.calendar_days+' calendar days. Assets on one day share a bootstrap block.</p></article><article class="card"><div class="eyebrow">Probability calibration</div><div class="big">'+num(pick.brier)+'</div><div class="sub">Brier score · lower is better</div><p class="details">Baseline '+num((m.baseline||{}).brier)+'. Paired improvement 95% interval: '+num(ci.low)+' to '+num(ci.high)+'.</p></article><article class="card"><div class="eyebrow">Daily roundtrip comparator</div><div class="big loss">'+pct(cmp.return)+'</div><div class="sub">'+currency+' return after declared fees & slippage</div><p class="details">Research simulation; no bot fills or actual portfolio replay. Double-cost stress: '+pct(cmp.stress_return)+'.</p></article></div><div class="grid2"><article class="card"><h3>Prespecified model comparisons</h3><div class="table-wrap"><table><thead><tr><th>Variant</th><th>Accuracy</th><th>Brier</th><th>Log loss</th><th>After costs</th></tr></thead><tbody>'+rows+'</tbody></table></div><p class="details">Selection frozen on earlier calibration. No parameter changes after viewing the holdout.</p></article><article class="card"><h3>Development fold consistency</h3><svg class="chart" viewBox="0 0 490 205" role="img" aria-label="Brier improvement over baseline for each chronological development fold"><line x1="28" x2="475" y1="90" y2="90" stroke="#455570"/><text x="28" y="15">Above baseline → better proper score</text>'+bars+'</svg><p class="details">'+(q.folds||[]).length+' chronological folds; green is positive improvement. Repeated resamples are uncertainty estimates, not new tests.</p></article></div>';
} $('currency').addEventListener('change',update);$('period').addEventListener('change',update);update(); const r=E.recorded_kimi;if(r){$('recorded').textContent=r.recorded_decisions+' decisions; '+r.recorded_candidates+' candidates; '+r.evaluated_candidates+' evaluable outcomes across '+r.calendar_days+' calendar days. Status: '+r.status+'. Censored cases: '+r.censored_candidates+'.';}
</script></body></html>'''
    for key,value in [('__FONT__',font),('__SIGNALS__',''.join(cards)),('__RECEIPTS__',str(snapshot.get('receipt_count',0))),('__SOURCES__',''.join(sources)),('__STAMP__',html.escape(stamp)),('__DATA__',data)]:
        page=page.replace(key,value)
    return page


def write_report(snapshot,directory):
    path=Path(__file__).parent.parent/'docs'/'evidence-strategy-results.json'
    evaluation=json.loads(path.read_text(encoding='utf-8')) if path.is_file() else {}
    atomic_text(directory,'report.html',render_report(snapshot,evaluation))
